;

do $$
declare
  n int;
begin
  update public.products p
  set price_jpy = s.price_jpy,
      volume_ml = s.volume_ml,
      category = s.category,
      ingredients = s.ingredients,
      features = s.features,
      source_raw = coalesce(p.source_raw, '{}'::jsonb) || s.raw
  from _spec s, public.projects pr
  where pr.id = p.project_id
    and pr.name = 'Leaf& Dew'
    and p.kind = 'own'
    and p.name = s.name;
  get diagnostics n = row_count;
  if n <> 6 then
    raise exception '자사 제품 6종 중 %종만 찾았습니다. projects_leaf_dew.sql 시드가 들어갔는지, 제품명이 바뀌지 않았는지 확인하세요', n;
  end if;
end;
$$;

commit;

